import { IssuesCloseOutlined } from '@ant-design/icons';
import { Avatar, Result, Space, Typography } from 'antd';
import { Component } from 'react';

class PageErrorBoundary extends Component {
  state = { hasError: false, errorInfo: '' };
  static getDerivedStateFromError(error) {
    return { hasError: true, errorInfo: error.message };
  }
  componentDidCatch(error, errorInfo) {
    console.error('PageErrorBoundary', error, errorInfo);
  }

  isOutBrowser = () =>
    /Firefox\/([\d.]+)/.test(navigator.userAgent) &&
    navigator.userAgent.match(/Firefox\/(\d+)/)[1] < 70;
  render() {
    if (this.state.hasError) {
      return (
        <Result
          icon={<IssuesCloseOutlined />}
          title="应用程序出现异常"
          style={{ minHeight: 'calc(100vh - 92px)' }}
          extra={
            this.isOutBrowser() ? (
              <Space
                direction="vertical"
                style={{
                  width: 530,
                  textAlign: 'left',
                  fontSize: 16,
                  background: '#fff',
                  padding: 16
                }}
              >
                <Typography.Text type="danger" keyboard>
                  1、当前浏览器版本过低，程序不兼容低版本浏览器，无法完成打开操作。
                </Typography.Text>
                <Typography.Text type="danger" keyboard>
                  2、请复制当前浏览器地址
                </Typography.Text>
                <Typography.Text code copyable={{ text: location.href }}>
                  {location.href}
                </Typography.Text>
                <Typography.Text type="danger" keyboard>
                  3、使用google chrome浏览器/谷歌浏览器打开本系统，完成上报操作。
                </Typography.Text>
                <Avatar
                  size={96}
                  shape="square"
                  src={`data:image/jpeg;base64,`}
                />
              </Space>
            ) : (
              this.state.errorInfo
            )
          }
        />
      );
    }
    return this.props.children;
  }
}

export default PageErrorBoundary;
